    neighbors = get_neighbors()

    def dfs(node):
        stack = [node]
        visited[node] = True
        while stack:
            current = stack.pop()
            for neighbor in neighbors[current]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    stack.append(neighbor)

    count = 0
    for i in range(n):
        if not visited[i]:
            dfs(i)
            count += 1
    return count
