    def dfs(node, visited):
        visited.add(node)
        for neighbor in range(n):
            if neighbor not in visited and any(edge == [node, neighbor] or edge == [neighbor, node] for edge in edges):
                dfs(neighbor, visited)

    visited = set()
    components = 0
    for node in range(n):
        if node not in visited:
            dfs(node, visited)
            components += 1
    return components
