            node = stack.pop()
            if node == end:
                return True
            if node in visited:
                continue
            visited.add(node)
            for neighbor, _ in graph.get(node, []):
                if neighbor not in visited:
                    stack.append(neighbor)
        return False

    if not is_reachable(s, t):
