    def get_adjacency_list(n, edges):
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)
        return adj

    def dfs(node, visited, adj):
        if visited[node]:
            return
        visited[node] = True
        for neighbor in adj[node]:
            dfs(neighbor, visited, adj)

    adj = get_adjacency_list(n, edges)
    visited = [False] * n
    components = 0

    for node in range(n):
        if not visited[node]:
            dfs(node, visited, adj)
            components += 1

    return components
