    from collections import defaultdict, deque

    if s == t:
        return 0

    # Build adjacency list with weights
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Bellman-Ford to detect negative cycles and find shortest paths
    # We need to check for reachability and negative cycles
    # We will use a modified Bellman-Ford to find shortest paths from s to t

    # Initialize distance array
    dist = [float('inf')] * n
    dist[s] = 0

    # Relax edges up to n-1 times
    for i in range(n - 1):
        updated = False
        for u in graph:
            for v, w in graph[u]:
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
                    updated = True
        if not updated:
            break

    # Check for negative weight cycles that are reachable from s
    # Add a dummy node to detect negative cycles
    # This is a common technique in Bellman-Ford
    # We add a new node (n) that connects to all other nodes with weight 0
    graph[n] = [(i, 0) for i in range(n)]
    for i in range(n):
        if dist[i] == float('inf'):
            continue
        for v, w in graph[i]:
            if dist[i] + w < dist[v]:
                dist[v] = dist[i] + w
                if i == n:
                    # Negative cycle found
                    return -1

    # Remove the dummy node from the distance array
    dist.pop()

    if dist[t] == float('inf'):
        return -1
    return dist[t]
